using System;
using System.Reflection;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonFinanceHistoryReviewVerification
    {
        static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
        static PythonFinanceDay Day(int day,bool business=false)
        {
            string label=day+"日目・"+(day==2 ? "休業日" : "営業日");return new PythonFinanceDay{day=day,label=label,presentation_version=1,headline=business ? "店の人気：12 / 獲得人気：2 / 交流件数：8\n接客評価・満足：5 / 普通：2 / 不満：1\n満員で帰った客：1 / 待ち切れず帰った客：2" : "資金 1100 → 800 / 純収支 -300\n総収入 100 / 総支出 400",breakdown=business ? "店の人気：12\n獲得人気：2\n接客評価・満足：5\n満員で帰った客：1\n目標結果：挑戦中\n席数：3" : "接客売上：200\n運営費：100\n用品購入費：300",comparison=day==1 ? "前日との差：比較できる記録なし" : "前日との差（当日−前日）\n純収支：-400",overview="従来の概要",details="従来の詳細"};
        }
        public static void BuildAndVerify()
        {
            PythonFinanceHistoryLayout.Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(client,preview);var pending=typeof(PythonStateClient).GetField("pending",flags);
            var state=PythonServiceSetup.Sample();state.instance_id="finance-review";state.closed=true;state.required_action="";state.finance_history=new PythonFinanceHistory{totals="記録期間の収支\n総収入 +300 / 総支出 +500 / 純収支 -200",notes="閉店済みの記録です。売上のボーナスは二重加算しません。",rows=new[]{Day(1),Day(2),Day(4)}};state.business_history=new PythonFinanceHistory{totals="閉店済みの記録：4日分",notes="記録不足は現在値やゼロで補いません。",rows=new[]{Day(1,true),Day(2,true),Day(3,true),Day(4,true)}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonFinanceHistoryPanel>();preview.GetComponent<PythonClosingPanel>().History();Check(p.panel.activeSelf && p.SelectedDay==4 && !p.next.interactable && p.summary.text.Contains("-300"),"Closing entry or latest");p.SelectDay(2);Capture(preview,"FinanceReviewDaily");p.SelectSection(1);Check(p.details.text.Contains("-400") && !p.details.text.Contains("用品購入"),"Comparison split");Capture(preview,"FinanceReviewComparison");p.Mode(1);Check(p.SelectedDay==2 && p.BusinessMode,"Mode lost date");p.SelectSection(0);Check(p.details.text.Contains("満員") && p.summary.text.Contains("接客評価"),"Business metrics");Capture(preview,"FinanceReviewBusiness");p.SelectSection(2);Check(p.details.text.Contains("4日分"),"Business period");p.Mode(0);Check(p.details.text.Contains("総収入 +300"),"Finance period");p.SelectSection(0);p.Next();Check(p.SelectedDay==3 && p.details.text.Contains("記録がありません"),"Missing same-day record");p.Mode(1);Check(p.SelectedDay==3 && p.details.text.Contains("席数"),"Available other mode");p.SelectDay(1);p.SelectSection(1);Check(p.details.text.Contains("比較できる記録なし") && !p.previous.interactable,"First comparison");state.revision++;apply();Check(p.SelectedDay==1 && p.Section==1 && p.BusinessMode,"Polling selection");
            p.SelectSection(0);state.business_history.rows[0].breakdown=new string('長',4000);apply();Canvas.ForceUpdateCanvases();var scroll=p.details.GetComponentInParent<ScrollRect>(true);Check(scroll.content.rect.height>scroll.viewport.rect.height,"Long detail scroll");var original=state.finance_history.rows;var many=new PythonFinanceDay[40];for(int i=0;i<many.Length;i++)many[i]=Day(i+1);state.finance_history.rows=many;apply();Canvas.ForceUpdateCanvases();Check(p.listContent.rect.height>p.listContent.GetComponentInParent<ScrollRect>(true).viewport.rect.height,"Date list scroll");state.finance_history.rows=original;apply();
            var menu=preview.GetComponent<PythonMenuPanel>();menu.Open();menu.SelectGroup(3);menu.Select(Array.IndexOf(PythonMenuPanel.Routes,27));Check(p.panel.activeSelf && p.close.GetComponentInChildren<Text>().text=="メニューへ戻る","Business menu entry");p.Mode(0);p.close.onClick.Invoke();Check(menu.panel.activeSelf && menu.SelectedGroup==3 && !p.panel.activeSelf,"Menu return after mode");
            p.Open();int selected=p.SelectedDay;pending.SetValue(client,new PythonShiftCommand{kind="save_game"});preview.RefreshPythonControls();p.SelectDay(2);p.Mode(1);Check(p.SelectedDay==selected && !p.BusinessMode && !p.modes[0].interactable,"Busy guard");pending.SetValue(client,null);apply();p.Disconnect();p.SelectDay(2);Check(p.SelectedDay==selected && !p.previous.interactable && p.notice.text.Contains("未接続"),"Offline guard");apply();state.finance_history.rows[0].presentation_version=0;p.SelectDay(1);Check(p.details.text.Contains("従来の詳細"),"Legacy fallback");
            state.instance_id="loaded";state.finance_history.rows=new PythonFinanceDay[0];state.business_history.rows=new PythonFinanceDay[0];apply();Check(!p.panel.activeSelf && p.SelectedDay==0 && p.Section==0 && !p.BusinessMode,"Load reset");p.Open();Check(p.details.text.Contains("まだ閉店") && !p.next.interactable && !p.previous.interactable,"Empty history");Check(pending.GetValue(client)==null,"Browsing sent command");Debug.Log("CAT_CAFE_FINANCE_REVIEW_OK: closing entry / latest and date list / sections / same day mode / missing record / first comparison / polling / long text / menu return / busy / offline / legacy / load / empty / read only");
        }
    }
}
